#!/usr/bin/env python3
"""Emits WinForms designer pages from the fields machine_pages.py produces."""
import os, re, sys
sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
from machine_pages import *

HDR = '''\ufeff// <auto-generated>
//   Generated by tools/emit_pages.py from {src}
//
//   Addresses and names are the ENGINEER'S OWN, straight from the label list.
//   Captions are translated from the Turkish device names. Divisors are starting
//   values by data type; angles are degrees and times are seconds.
// </auto-generated>

namespace {ns}
{{
    partial class {cls}
    {{
        private System.ComponentModel.IContainer components = null;
        protected override void Dispose(bool disposing)
        {{
            if (disposing && (components != null)) components.Dispose();
            base.Dispose(disposing);
        }}

        #region Component Designer generated code
        private void InitializeComponent()
        {{
'''

FTR = '''            this.AutoScroll = true;
            this.BackColor = System.Drawing.Color.White;
            this.Name = "{cls}";
            this.Size = new System.Drawing.Size(1060, 700);
            this.ResumeLayout(false);
        }}
        #endregion
'''

CB = '''\ufeff// <auto-generated>  see the .Designer.cs  </auto-generated>
using System.Windows.Forms;

namespace {ns}
{{
    public partial class {cls} : UserControl
    {{
        public {cls}() {{ InitializeComponent(); }}
    }}
}}
'''

class Emitter:
    def __init__(self, ns, outdir, src, plc=1):
        self.ns, self.outdir, self.src, self.plc = ns, outdir, src, plc

    def emit(self, cls, fields, cols=2):
        decl, body, used = [], [], set()
        x, y = 16, 16
        COLW, MAXY = 520, 655

        def place(h):
            nonlocal x, y
            if y + h > MAXY:
                y = 16; x += COLW
            p = (x, y); y += h + 6
            return p

        def name_for(cap, pfx):
            base = (pfx + ident(cap))[:44]
            n = base; i = 2
            while n in used: n = base + str(i); i += 1
            used.add(n); return n

        for f in fields:
            cap = (f["caption"] or "").replace('"', "'")[:52] or "Field"
            k = f["kind"]

            if k == "unit":
                nm = name_for(cap, "u")
                px, py = place(66)
                decl.append("            this.%s = new Kaban.UI.Controls.FunctionUnitHMI();" % nm)
                ut, sfx, dec = unit_for(f["caption"])
                b = ['this.{0}.Name = "{0}";'.format(nm),
                     'this.{0}.PlcNumber = {1};'.format(nm, self.plc),
                     'this.{0}.TitleTextKey = "{1}";'.format(nm, cap),
                     'this.{0}.BackColor = System.Drawing.Color.White;'.format(nm),
                     'this.{0}.Location = new System.Drawing.Point({1}, {2});'.format(nm, px, py),
                     'this.{0}.Size = new System.Drawing.Size(488, 62);'.format(nm),
                     'this.{0}.LogAction = true;'.format(nm),
                     'this.{0}.CommandAAddress = "{1}";'.format(nm, f["back"]["addr"]),
                     'this.{0}.CommandAAction = Kaban.Core.Enums.BitActionType.Momentary;'.format(nm),
                     'this.{0}.CommandBAddress = "{1}";'.format(nm, f["fwd"]["addr"]),
                     'this.{0}.CommandBAction = Kaban.Core.Enums.BitActionType.Momentary;'.format(nm)]
                if f.get("lamp_back"):
                    b.append('this.{0}.Lamp1AAddress = "{1}";'.format(nm, f["lamp_back"]["addr"]))
                if f.get("lamp_fwd"):
                    b.append('this.{0}.Lamp1BAddress = "{1}";'.format(nm, f["lamp_fwd"]["addr"]))
                if f.get("pos"):
                    p = f["pos"]
                    b += ['this.{0}.PositionAddress = "{1}";'.format(nm, p["addr"]),
                          'this.{0}.PositionDataType = Kaban.Core.Enums.DataTypeEnum.{1};'.format(
                              nm, "Bin_32" if is_32(p["dtype"]) else "Bin_16"),
                          'this.{0}.PositionDivisor = {1}D;'.format(nm, divisor_for(p["dtype"], ut, sfx)),
                          'this.{0}.PositionDecimalPlaces = {1};'.format(nm, dec),
                          'this.{0}.PositionDigits = 7;'.format(nm),
                          'this.{0}.PositionSuffix = "{1}";'.format(nm, sfx),
                          'this.{0}.PositionUnitType = Kaban.Core.Enums.UnitType.{1};'.format(nm, ut)]
                b.append('this.{0}.RequiredSecurity = Kaban.Core.Enums.SecurityLevel.Operator;'.format(nm))
                b.append('this.Controls.Add(this.{0});'.format(nm))

            elif k == "button":
                nm = name_for(cap, "b")
                px, py = place(40)
                decl.append("            this.%s = new Kaban.UI.Controls.ButtonHMI();" % nm)
                b = ['this.{0}.Name = "{0}";'.format(nm),
                     'this.{0}.PlcNumber = {1};'.format(nm, self.plc),
                     'this.{0}.FallbackText = "{1}";'.format(nm, cap),
                     'this.{0}.BitActions.Add(new Kaban.Core.Models.BitAction {{ Address = "{1}", Action = Kaban.Core.Enums.BitActionType.Momentary }});'.format(nm, f["cmd"]["addr"]),
                     'this.{0}.Lamp1Address = "{1}";'.format(nm, (f.get("lamp") or f["cmd"])["addr"]),
                     'this.{0}.Location = new System.Drawing.Point({1}, {2});'.format(nm, px, py),
                     'this.{0}.Size = new System.Drawing.Size(300, 36);'.format(nm),
                     'this.{0}.LogAction = true;'.format(nm),
                     'this.{0}.RequiredSecurity = Kaban.Core.Enums.SecurityLevel.Operator;'.format(nm),
                     'this.Controls.Add(this.{0});'.format(nm)]

            elif k == "lamp":
                nm = name_for(cap, "l")
                px, py = place(30)
                decl.append("            this.%s = new Kaban.UI.Controls.LampHMI();" % nm)
                b = ['this.{0}.Name = "{0}";'.format(nm),
                     'this.{0}.PlcNumber = {1};'.format(nm, self.plc),
                     'this.{0}.Address = "{1}";'.format(nm, f["cmd"]["addr"]),
                     'this.{0}.DescriptionText = "{1}";'.format(nm, cap),
                     'this.{0}.Location = new System.Drawing.Point({1}, {2});'.format(nm, px, py),
                     'this.{0}.Size = new System.Drawing.Size(300, 26);'.format(nm),
                     'this.Controls.Add(this.{0});'.format(nm)]

            elif k == "check":
                nm = name_for(cap, "c")
                px, py = place(32)
                decl.append("            this.%s = new Kaban.UI.Controls.CheckBoxHMI();" % nm)
                b = ['this.{0}.Name = "{0}";'.format(nm),
                     'this.{0}.PlcNumber = {1};'.format(nm, self.plc),
                     'this.{0}.Address = "{1}";'.format(nm, f["cmd"]["addr"]),
                     'this.{0}.DescriptionText = "{1}";'.format(nm, cap),
                     'this.{0}.Location = new System.Drawing.Point({1}, {2});'.format(nm, px, py),
                     'this.{0}.Size = new System.Drawing.Size(440, 28);'.format(nm),
                     'this.{0}.LogAction = true;'.format(nm),
                     'this.{0}.RequiredSecurity = Kaban.Core.Enums.SecurityLevel.Maintenance;'.format(nm),
                     'this.Controls.Add(this.{0});'.format(nm)]

            else:                                   # num / display
                writable = (k == "num")
                nm = name_for(cap, "n" if writable else "d")
                px, py = place(36)
                kind = "NumericInputHMI" if writable else "NumericDisplayHMI"
                decl.append("            this.%s = new Kaban.UI.Controls.%s();" % (nm, kind))
                ut, sfx, dec = unit_for(f["caption"])
                b = ['this.{0}.Name = "{0}";'.format(nm),
                     'this.{0}.PlcNumber = {1};'.format(nm, self.plc),
                     'this.{0}.Address = "{1}";'.format(nm, f["cmd"]["addr"]),
                     'this.{0}.DataType = Kaban.Core.Enums.DataTypeEnum.{1};'.format(
                         nm, "Bin_32" if is_32(f["cmd"]["dtype"]) else "Bin_16"),
                     'this.{0}.Divisor = {1}D;'.format(nm, divisor_for(f["cmd"]["dtype"], ut, sfx)),
                     'this.{0}.DecimalPlaces = {1};'.format(nm, dec),
                     'this.{0}.Digits = 7;'.format(nm),
                     'this.{0}.Suffix = "{1}";'.format(nm, sfx),
                     'this.{0}.UnitType = Kaban.Core.Enums.UnitType.{1};'.format(nm, ut),
                     'this.{0}.DescriptionText = "{1}";'.format(nm, cap),
                     'this.{0}.Location = new System.Drawing.Point({1}, {2});'.format(nm, px, py),
                     'this.{0}.Size = new System.Drawing.Size(440, 32);'.format(nm),
                     'this.Controls.Add(this.{0});'.format(nm)]
                if writable:
                    b.insert(-1, 'this.{0}.RequiredSecurity = Kaban.Core.Enums.SecurityLevel.Maintenance;'.format(nm))

            body.append("            // \n            // {0}\n            // \n".format(nm) +
                        "\n".join("            " + line for line in b) + "\n")

        fields_decl = "\n".join("        private Kaban.UI.Controls.{0} {1};".format(
            re.search(r"new Kaban\.UI\.Controls\.(\w+)\(\)", d).group(1),
            re.search(r"this\.(\w+) =", d).group(1)) for d in decl)

        text = (HDR.format(ns=self.ns, cls=cls, src=self.src) + "\n".join(decl) +
                "\n            this.SuspendLayout();\n" + "".join(body) +
                FTR.format(cls=cls) + "\n" + fields_decl + "\n    }\n}\n")

        os.makedirs(self.outdir, exist_ok=True)
        open(os.path.join(self.outdir, cls + ".Designer.cs"), "w",
             encoding="utf-8", newline="\r\n").write(text)
        open(os.path.join(self.outdir, cls + ".cs"), "w",
             encoding="utf-8", newline="\r\n").write(CB.format(ns=self.ns, cls=cls))
        return len(decl)

